def pinned(value):
    """Copy the frozen graph, renaming every reference into its frozen namespace."""
    result = copy.deepcopy(value)
    def rewrite(item):
        if isinstance(item, dict):
            if '$ref' in item:
                item['$ref'] += SUFFIX
            for child in item.values():
                rewrite(child)
        elif isinstance(item, list):
            for child in item:
                rewrite(child)
    rewrite(result)
    return result


def definitions():
    return {name + SUFFIX: pinned(value) for name, value in DEFINITIONS.items()}


def write_tools(directory):
    import json
    for version, manifest in MANIFESTS.items():
        name = 'factory-tools.v' + version.rsplit('.', 1)[0] + '.schema.json'
        (directory / name).write_text(json.dumps(pinned(manifest), indent=2) + '\n')
